from docx import Document
from docx.oxml.ns import qn
p='/work/complaint_preparation.docx'; d=Document(p)
print('paras',len(d.paragraphs),'tables',len(d.tables),'bytes')
for s in ['一、案件与金额梳理','二、诉讼请求与风险分析','三、民事起诉状草稿','四、材料目录与证明目的','民事起诉状']:
 print(s, any(s in x.text for x in d.paragraphs))
# validate explicit font mappings on each run, paragraph heading styles
bad=[]
for i,pa in enumerate(d.paragraphs):
 for run in pa.runs:
  rf=run._element.rPr.rFonts if run._element.rPr is not None else None
  if rf is None or any(rf.get(qn('w:'+a)) != ('SimHei' if run.font.name=='SimHei' else 'FangSong') for a in ('ascii','hAnsi','eastAsia','cs')):
   bad.append(('p',i,run.text,run.font.name))
for ti,t in enumerate(d.tables):
 for ri,row in enumerate(t.rows):
  for ci,c in enumerate(row.cells):
   for pa in c.paragraphs:
    for run in pa.runs:
     rf=run._element.rPr.rFonts if run._element.rPr is not None else None
     if rf is None or any(rf.get(qn('w:'+a))!='FangSong' for a in ('ascii','hAnsi','eastAsia','cs')): bad.append(('t',ti,ri,ci,run.text))
print('bad font runs',len(bad),bad[:5])
# Check styles font explicit on headings
for s in ['Title','Heading 1','Heading 2','Heading 3']:
 st=d.styles[s]; rf=st._element.rPr.rFonts
 print(s,st.font.name,[rf.get(qn('w:'+a)) for a in ('ascii','hAnsi','eastAsia','cs')])
